function pageNumbers(cur,max){if(max<=5)return Array.from({length:max},(_,i)=>i+1);const nums=[1,cur-1,cur,cur+1,max].filter((x,i,a)=>x>=1&&x<=max&&a.indexOf(x)===i).sort((a,b)=>a-b);const out=[];nums.forEach((n,i)=>{if(i&&n-nums[i-1]>1)out.push("…");out.push(n);});return out;}
