function renderFilterOptions(){fillOptions("#filter-nature",state.rows.map(r=>r.nature),"All natures");fillOptions("#filter-method",state.rows.map(r=>r.method),"All methods");fillOptions("#filter-district",state.rows.map(r=>r.district),"All districts");fillOptions("#filter-org",state.rows.map(r=>r.org),"All organizations");fillOptions("#filter-pe",state.rows.map(r=>r.pe),"All entities");fillOptions("#insight-district",state.rows.map(r=>r.district),"All districts");}
